"""Extract network information for a docker container."""
def __extract_network_from_docker_container(docker_container: Any) -> object {
    network_bindings = docker_container.get("networkBindings");
    bindings = [];
    if network_bindings {
        bindings = [
            (
                network["bindIP"]
                + " ("
                + str(network["hostPort"])
                + "[host] -> "
                + str(network["containerPort"])
                + "[network])"
            ) for network in network_bindings
        ];
    }
    if (bindings is []) {
        bindings = "no network binding";
    } else {
        bindings = ", ".join(bindings);
    }
    return (docker_container["name"] + " -> " + bindings);
}

"""
    Strip characters that the APIC deems are illegal

    :param name: String to remove the illegal characters
    :return: String with the illegal characters removed
    """
def strip_illegal_characters(name: Any) -> object {
    chars_all_good = True;
    for character in name {
        if (character.isalnum() or (character in ('_', '.', ':', '-'))) {
            continue;
        }
        chars_all_good = False;
        name = name.replace(character, '');
    }
    if chars_all_good {
        return name;
    }
    return strip_illegal_characters(name);
}

